// usr/system/sigma_process.rs — Sigma Process Monitor
//
// Implements htop/btop-style process monitoring with real-time
// CPU, memory, and I/O statistics visualization.
//
// Language: Rust (std for userland applications)

use std::collections::HashMap;

// ─── Process Types ─────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct Process {
    pub pid: u32,
    pub name: String,
    pub user: String,
    pub state: String,
    pub cpu_percent: f64,
    pub memory_percent: f64,
    pub memory_mb: f64,
    pub threads: u32,
    pub priority: i32,
    pub command: String,
    pub running_time: String,
}

#[derive(Debug, Clone)]
pub struct SystemStats {
    pub cpu_usage: f64,
    pub memory_total: u64,
    pub memory_used: u64,
    pub memory_free: u64,
    pub memory_percent: f64,
    pub swap_total: u64,
    pub swap_used: u64,
    pub load_average: (f64, f64, f64),
    pub uptime: u64,
    pub process_count: u32,
    pub thread_count: u32,
}

// ─── Process Monitor ───────────────────────────────────────────────────────

pub struct ProcessMonitor {
    pub processes: HashMap<u32, Process>,
    pub system_stats: SystemStats,
    pub sort_field: String,
    pub sort_descending: bool,
    pub filter: String,
}

impl ProcessMonitor {
    pub fn new() -> Self {
        let mut monitor = ProcessMonitor {
            processes: HashMap::new(),
            system_stats: SystemStats {
                cpu_usage: 0.0,
                memory_total: 16 * 1024 * 1024 * 1024,  // 16 GB
                memory_used: 8 * 1024 * 1024 * 1024,     // 8 GB
                memory_free: 8 * 1024 * 1024 * 1024,     // 8 GB
                memory_percent: 50.0,
                swap_total: 4 * 1024 * 1024 * 1024,     // 4 GB
                swap_used: 0,
                load_average: (1.2, 1.5, 1.8),
                uptime: 86400,  // 1 day
                process_count: 0,
                thread_count: 0,
            },
            sort_field: "cpu".to_string(),
            sort_descending: true,
            filter: String::new(),
        };
        
        monitor.init_sample_processes();
        monitor
    }

    /// Initialize sample processes
    fn init_sample_processes(&mut self) {
        let sample_processes = vec![
            Process {
                pid: 1,
                name: "init".to_string(),
                user: "root".to_string(),
                state: "S".to_string(),
                cpu_percent: 0.0,
                memory_percent: 0.1,
                memory_mb: 16.0,
                threads: 1,
                priority: 0,
                command: "/sbin/init".to_string(),
                running_time: "1d".to_string(),
            },
            Process {
                pid: 100,
                name: "sshd".to_string(),
                user: "root".to_string(),
                state: "S".to_string(),
                cpu_percent: 0.2,
                memory_percent: 0.5,
                memory_mb: 80.0,
                threads: 4,
                priority: 0,
                command: "/usr/sbin/sshd -D".to_string(),
                running_time: "12h".to_string(),
            },
            Process {
                pid: 234,
                name: "firefox".to_string(),
                user: "user".to_string(),
                state: "R".to_string(),
                cpu_percent: 15.5,
                memory_percent: 8.2,
                memory_mb: 1312.0,
                threads: 32,
                priority: 0,
                command: "/usr/bin/firefox".to_string(),
                running_time: "2h".to_string(),
            },
            Process {
                pid: 567,
                name: "code".to_string(),
                user: "user".to_string(),
                state: "S".to_string(),
                cpu_percent: 5.3,
                memory_percent: 6.8,
                memory_mb: 1088.0,
                threads: 24,
                priority: 0,
                command: "/usr/bin/code".to_string(),
                running_time: "4h".to_string(),
            },
            Process {
                pid: 890,
                name: "node".to_string(),
                user: "user".to_string(),
                state: "R".to_string(),
                cpu_percent: 12.8,
                memory_percent: 4.5,
                memory_mb: 720.0,
                threads: 8,
                priority: 0,
                command: "/usr/bin/node server.js".to_string(),
                running_time: "1h".to_string(),
            },
            Process {
                pid: 1234,
                name: "python".to_string(),
                user: "user".to_string(),
                state: "S".to_string(),
                cpu_percent: 3.2,
                memory_percent: 2.1,
                memory_mb: 336.0,
                threads: 2,
                priority: 0,
                command: "/usr/bin/python script.py".to_string(),
                running_time: "30m".to_string(),
            },
            Process {
                pid: 2345,
                name: "docker".to_string(),
                user: "root".to_string(),
                state: "S".to_string(),
                cpu_percent: 1.5,
                memory_percent: 3.8,
                memory_mb: 608.0,
                threads: 16,
                priority: 0,
                command: "/usr/bin/docker daemon".to_string(),
                running_time: "6h".to_string(),
            },
            Process {
                pid: 3456,
                name: "postgres".to_string(),
                user: "postgres".to_string(),
                state: "S".to_string(),
                cpu_percent: 2.1,
                memory_percent: 5.2,
                memory_mb: 832.0,
                threads: 12,
                priority: 0,
                command: "/usr/bin/postgres".to_string(),
                running_time: "8h".to_string(),
            },
        ];
        
        for process in sample_processes {
            self.processes.insert(process.pid, process);
        }
        
        self.system_stats.process_count = self.processes.len() as u32;
        self.system_stats.thread_count = self.processes.values().map(|p| p.threads).sum();
    }

    /// Update system statistics
    pub fn update_stats(&mut self) {
        // Simulate CPU fluctuation
        self.system_stats.cpu_usage = (self.system_stats.cpu_usage * 0.9) + (self.processes.values().map(|p| p.cpu_percent).sum::<f64>() / 100.0 * 10.0);
        
        // Simulate memory fluctuation
        let used_mb: f64 = self.processes.values().map(|p| p.memory_mb).sum();
        self.system_stats.memory_used = (used_mb * 1024.0 * 1024.0) as u64;
        self.system_stats.memory_free = self.system_stats.memory_total - self.system_stats.memory_used;
        self.system_stats.memory_percent = (self.system_stats.memory_used as f64 / self.system_stats.memory_total as f64) * 100.0;
        
        // Update load average
        self.system_stats.load_average = (
            self.system_stats.load_average.0 * 0.95 + self.system_stats.cpu_usage / 100.0 * 0.05,
            self.system_stats.load_average.1 * 0.95 + self.system_stats.cpu_usage / 100.0 * 0.05,
            self.system_stats.load_average.2 * 0.95 + self.system_stats.cpu_usage / 100.0 * 0.05,
        );
    }

    /// Get sorted processes
    pub fn get_sorted_processes(&self) -> Vec<&Process> {
        let mut processes: Vec<&Process> = self.processes.values()
            .filter(|p| self.filter.is_empty() || p.name.to_lowercase().contains(&self.filter.to_lowercase()))
            .collect();
        
        processes.sort_by(|a, b| {
            let a_val = match self.sort_field.as_str() {
                "pid" => a.pid as f64,
                "name" => a.name.len() as f64,
                "cpu" => a.cpu_percent,
                "mem" => a.memory_percent,
                "time" => a.threads as f64,
                _ => a.cpu_percent,
            };
            
            let b_val = match self.sort_field.as_str() {
                "pid" => b.pid as f64,
                "name" => b.name.len() as f64,
                "cpu" => b.cpu_percent,
                "mem" => b.memory_percent,
                "time" => b.threads as f64,
                _ => b.cpu_percent,
            };
            
            if self.sort_descending {
                b_val.partial_cmp(&a_val).unwrap_or(std::cmp::Ordering::Equal)
            } else {
                a_val.partial_cmp(&b_val).unwrap_or(std::cmp::Ordering::Equal)
            }
        });
        
        processes
    }

    /// Kill process
    pub fn kill_process(&mut self, pid: u32) -> Result<(), String> {
        if self.processes.contains_key(&pid) {
            self.processes.remove(&pid);
            self.system_stats.process_count = self.processes.len() as u32;
            Ok(())
        } else {
            Err("Process not found".to_string())
        }
    }

    /// Get process by PID
    pub fn get_process(&self, pid: u32) -> Option<&Process> {
        self.processes.get(&pid)
    }

    /// Set sort field
    pub fn set_sort(&mut self, field: String) {
        self.sort_field = field;
    }

    /// Toggle sort direction
    pub fn toggle_sort(&mut self) {
        self.sort_descending = !self.sort_descending;
    }

    /// Set filter
    pub fn set_filter(&mut self, filter: String) {
        self.filter = filter;
    }

    /// Format memory
    pub fn format_memory(&self, bytes: u64) -> String {
        if bytes >= 1024 * 1024 * 1024 {
            format!("{:.1} GB", bytes as f64 / (1024.0 * 1024.0 * 1024.0))
        } else if bytes >= 1024 * 1024 {
            format!("{:.1} MB", bytes as f64 / (1024.0 * 1024.0))
        } else if bytes >= 1024 {
            format!("{:.1} KB", bytes as f64 / 1024.0)
        } else {
            format!("{} B", bytes)
        }
    }
}

// ─── CLI Interface ─────────────────────────────────────────────────────────

